import 'package:flutter/material.dart'; import 'package:uuid/uuid.dart'; import '../../models/exam_model.dart'; import '../../models/question_model.dart'; import '../../models/result_model.dart'; import '../../repositories/exam_repository.dart'; import '../../repositories/result_repository.dart'; import '../../services/auth_service.dart'; import '../../widgets/question_widget.dart'; import 'exam_result_page.dart'; class TakeExamPage extends StatefulWidget { final ExamModel exam; const TakeExamPage({super.key,required this.exam}); @override State<TakeExamPage> createState()=>_TakeExamPageState(); } class _TakeExamPageState extends State<TakeExamPage>{ Map<String,String> answers={}; Future<void> submit(List<QuestionModel> qs) async {double total=0,earned=0;for(final q in qs){total+=q.points; if((answers[q.id]??'').trim().toLowerCase()==q.correctAnswer.trim().toLowerCase())earned+=q.points;}final score=total==0?0:earned/total*100;final result=ResultModel(id:const Uuid().v4(),studentId:AuthService().currentUser!.uid,examId:widget.exam.id,courseId:widget.exam.courseId,score:score,passed:score>=widget.exam.passScore,submittedAt:DateTime.now());await ResultRepository().save(result);if(mounted)Navigator.pushReplacement(context,MaterialPageRoute(builder:(_)=>ExamResultPage(result:result)));} @override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:Text(widget.exam.title)),body:StreamBuilder(stream:ExamRepository().questions(widget.exam.id),builder:(c,s){if(!s.hasData)return const Center(child:CircularProgressIndicator());final qs=s.data!;return ListView(padding:const EdgeInsets.all(12),children:[...qs.map((q)=>Padding(padding:const EdgeInsets.only(bottom:10),child:QuestionWidget(question:q,value:answers[q.id],onChanged:(v)=>setState(()=>answers[q.id]=v??'')))),FilledButton(onPressed:()=>submit(qs),child:const Text('إنهاء وتسليم الاختبار'))]);})); }